def nextGeneration(board):
    rows, cols = len(board), len(board[0])
    res = [[0] * cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            live = 0
            for di in (-1, 0, 1):
                for dj in (-1, 0, 1):
                    if di == 0 and dj == 0:
                        continue
                    a, b = i + di, j + dj
                    if 0 <= a < rows and 0 <= b < cols:
                        live += board[a][b]
            if live == 3 or (board[i][j] == 1 and live == 2):
                res[i][j] = 1
    return res
